   }

+  if constexpr (D == tmol::Device::CPU) {
+    if (!output_block_pair_energies) {
+      for (int p = 0; p < n_poses; ++p) {
+        for (int term = 0; term < 3; ++term) {
+          output[term][p][0][0] = cpu_pose_accum[3 * p + term];
+        }
+      }
+    }
